func TestVendorNamedThemesAndDarkVariant(t *testing.T) {
	for _, theme := range []struct {
		name string
		css  func() string
	}{{"appkit", tokens.ThemeCSS}, {"synthwave", synthwave.CSS}, {"copper", copper.CSS}, {"lagoon", lagoon.CSS}, {"orchard", orchard.CSS}, {"geoff-indigo", geoffindigo.CSS}, {"geoff-synthwave", geoffsynthwave.CSS}} {
		t.Run(theme.name, func(t *testing.T) {
			for _, variant := range []string{"none", "attribute"} {
				t.Run(variant, func(t *testing.T) {
					out := t.TempDir()
					args := []string{"--out", out, "--include", "tokens", "--theme", theme.name}
					want := tokens.StripDarkVariant(theme.css())
					if variant == "attribute" {
						args = append(args, "--dark-variant", variant)
						want = theme.css()
					}
					if err := vendorCmd(args); err != nil {
						t.Fatal(err)
					}
					files := readVendorThemeFiles(t, out)
					if len(files) != 2 || files["theme.css"] != want {
						t.Fatal("named theme bytes or output set changed")
					}
					if strings.Contains(files["theme.css"], "@custom-variant dark") != (variant == "attribute") {
						t.Fatal("dark variant did not follow the explicit option")
					}
					if theme.name == "appkit" {
						if strings.Contains(files[lockName], "\ntheme\t") {
							t.Fatal("default lock shape gained theme metadata")
						}
					} else if !strings.Contains(files[lockName], "\ntheme\t"+theme.name+"\n") {
						t.Fatal("named theme provenance missing")
					}
					if err := vendorCmd(append(args, "--check")); err != nil {
						t.Fatal("fresh named theme failed check", err)
					}
					otherVariant := "attribute"
					if variant == "attribute" {
						otherVariant = "none"
					}
					if err := vendorCmd(append(args, "--dark-variant", otherVariant, "--check")); err == nil || !strings.Contains(err.Error(), "theme.css") {
						t.Fatal("explicit theme check ignored requested dark-variant bytes")
					}
					if err := vendorCmd(args); err != nil {
						t.Fatal(err)
					}
					if !reflect.DeepEqual(files, readVendorThemeFiles(t, out)) {
						t.Fatal("named-theme replay changed bytes")
					}
				})
			}
		})
	}
}

func TestVendorThemeDefaultBytesAndLegacyLock(t *testing.T) {
	implicit, explicit := t.TempDir(), t.TempDir()
	if err := vendorCmd([]string{"--out", implicit, "--include", "tokens"}); err != nil {
		t.Fatal(err)
	}
	if err := vendorCmd([]string{"--out", explicit, "--include", "tokens", "--theme", "appkit", "--dark-variant", "none"}); err != nil {
		t.Fatal(err)
	}
	got := readVendorThemeFiles(t, implicit)
	if !reflect.DeepEqual(got, readVendorThemeFiles(t, explicit)) {
		t.Fatal("implicit and explicit defaults differ")
	}
	css := tokens.StripDarkVariant(tokens.ThemeCSS())
	if got["theme.css"] != css {
		t.Fatal("default CSS no longer matches existing token export")
	}
	wantLock := "# kit.lock — generated by `appkit vendor`. Do not edit.\n" +
		"# Re-run the vendor command to update; run it with --check in CI.\n" +
		"# A vendored file edited in place is a fork: fix the kit, or record a\n" +
		"# DIVERGENCE in the consuming repo (ADR-0017 §2).\n" +
		fmt.Sprintf("module\t%s\nversion\t%s\ndark-variant\tnone\ninclude\ttokens(L1)\n\nsha256\t%s\ttheme.css\n", modulePath, moduleVersion(), sum(css))
	if got[lockName] != wantLock {
		t.Fatal("default kit.lock changed from its pre-theme shape")
	}
}

func TestVendorThemeSwitchAndDesiredBytesDrift(t *testing.T) {
	out := t.TempDir()
	for _, name := range []string{"appkit", "synthwave", "copper", "lagoon", "orchard", "geoff-indigo", "geoff-synthwave", "appkit"} {
		args := []string{"--out", out, "--include", "tokens", "--theme", name}
		if err := vendorCmd(args); err != nil {
			t.Fatal(err)
		}
		before := readVendorThemeFiles(t, out)
		if len(before) != 2 {
			t.Fatal("theme switch left more than one active CSS artifact")
		}
		if err := vendorCmd(append(args, "--check")); err != nil {
			t.Fatal(err)
		}
		other := "appkit"
		if name == other {
			other = "synthwave"
		}
		if err := vendorCmd([]string{"--out", out, "--include", "tokens", "--theme", other, "--check"}); err == nil || !strings.Contains(err.Error(), "theme.css") {
			t.Fatal("check accepted bytes belonging to a different requested theme")
		}
		if err := os.WriteFile(filepath.Join(out, "theme.css"), []byte(before["theme.css"]+"\n"), 0644); err != nil {
			t.Fatal(err)
		}
		if err := vendorCmd(append(args, "--check")); err == nil || !strings.Contains(err.Error(), "theme.css") {
			t.Fatal("edited named-theme bytes passed check")
		}
		if err := os.WriteFile(filepath.Join(out, "theme.css"), []byte(before["theme.css"]), 0644); err != nil {
			t.Fatal(err)
		}
		if !reflect.DeepEqual(before, readVendorThemeFiles(t, out)) {
			t.Fatal("check mutated a theme or its lock")
		}
	}
}

func TestVendorThemeInvalidRequestsDoNotWrite(t *testing.T) {
	for _, options := range [][]string{
		{"--include", "tokens", "--theme", "unknown"},
		{"--include", "tokens", "--theme", ""},
		{"--include", "tokens", "--theme", "Geoff"},
		{"--include", "tokens", "--theme", "geoff"},
		{"--include", "motion", "--theme", "geoff-indigo"},
		{"--include", "appearance,router", "--theme", "synthwave"},
		{"--include", "motion", "--theme", "geoff-synthwave"},
		{"--include", "motion", "--theme", "copper"},
		{"--include", "motion", "--theme", "lagoon"},
		{"--include", "motion", "--theme", "orchard"},
		{"--include", "tokens", "--theme", "geoff-indigo", "--dark-variant", "media"},
	} {
		for _, check := range []bool{false, true} {
			parent := t.TempDir()
			out := filepath.Join(parent, "not-created")
			args := append([]string{"--out", out}, options...)
			if check {
				args = append(args, "--check")
			}
			if err := vendorCmd(args); err == nil {
				t.Fatal("invalid or ignored theme choice accepted", options)
			}
			if _, err := os.Stat(out); !os.IsNotExist(err) {
				t.Fatal("invalid theme request created output")
			}
			if err := os.Mkdir(out, 0700); err != nil {
				t.Fatal(err)
			}
			if err := os.WriteFile(filepath.Join(out, "theme.css"), []byte("consumer-owned"), 0600); err != nil {
				t.Fatal(err)
			}
			before := readVendorThemeFiles(t, out)
			if err := vendorCmd(args); err == nil {
				t.Fatal("invalid theme request accepted existing output")
			}
			if !reflect.DeepEqual(before, readVendorThemeFiles(t, out)) {
				t.Fatal("invalid request changed existing files")
			}
		}
	}
	out := t.TempDir()
	if err := vendorCmd([]string{"--out", out, "--include", "motion", "--theme", "appkit"}); err != nil {
		t.Fatal("explicit default theme should not require tokens", err)
	}
	if _, exists := readVendorThemeFiles(t, out)["theme.css"]; exists {
		t.Fatal("default theme expanded the selected export groups")
	}
}

func TestVendorCheckWithoutThemePreservesHistoricalLock(t *testing.T) {
	out := t.TempDir()
	sets, err := selectVendorSets("tokens")
	if err != nil {
		t.Fatal(err)
	}
	// A synthetic older artifact remains clean when its recorded bytes match.
	// The theme flag is the opt-in to checking the currently selected CSS.
	files := map[string]string{"theme.css": "/* synthetic historical CSS */\n"}
	if err := writeVendor(out, files, sets, vendorOptions{darkVariant: tokens.DarkVariantNone}); err != nil {
		t.Fatal(err)
	}
	before := readVendorThemeFiles(t, out)
	args := []string{"--out", out, "--include", "tokens", "--check"}
	if err := vendorCmd(args); err != nil {
		t.Fatal("implicit check stopped honoring a valid historical lock", err)
	}
	if err := vendorCmd(append(args, "--theme", "appkit")); err == nil || !strings.Contains(err.Error(), "theme.css") {
		t.Fatal("explicit appkit choice accepted historical different CSS")
	}
	if !reflect.DeepEqual(before, readVendorThemeFiles(t, out)) {
		t.Fatal("read-only checks changed historical artifacts")
	}
}

func readVendorThemeFiles(t *testing.T, dir string) map[string]string {
	t.Helper()
	entries, err := os.ReadDir(dir)
	if err != nil {
		t.Fatal(err)
	}
	files := map[string]string{}
	for _, entry := range entries {
		body, err := os.ReadFile(filepath.Join(dir, entry.Name()))
		if err != nil {
			t.Fatal(err)
		}
		files[entry.Name()] = string(body)
	}
	return files
}
